"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["6612"],{59311(e){e.exports=JSON.parse('{"id":"F196","slug":"supply-chain-finance-return","name":"Early-Payment Discount Return (Supply Chain Finance)","subject":"Corporate Finance","section":"Working Capital Management","topic":"Supply chain finance","level":"Intermediate","aliases":["dynamic discounting","supply chain finance","annualized discount return"],"formula":{"latex":"\\\\text{Annualized return}=\\\\frac{d}{1-d}\\\\times\\\\frac{365}{\\\\text{days early}}","also":[],"text":"Annualized return = d / (1 - d) x 365 / Days paid early"},"symbols":[{"symbol":"d","meaning":"Discount given for paying early, as a decimal","unit":"decimal"},{"symbol":"Days early","meaning":"How many days sooner the invoice is paid","unit":"days"}],"when_to_use":"Use it to compare an early-payment discount with the return you would earn elsewhere. A buyer with spare cash earns this return by paying a supplier early, and a supplier should compare it with the cost of its other funding.","worked_example":{"problem":"A buyer pays an invoice 20 days early in return for a 1% discount. What annualized return does that earn?","inputs":{"d":1,"days":20},"steps":[{"label":"Return for the period = d / (1 - d)","working":"0.01 / (1-0.01)","value":"1.01%"},{"label":"Simple annualized = return x 365 / days","working":"0.010101 x 365 / 20","value":"18.43%"},{"label":"Compounded = (1 + return)^(365 / days) - 1","working":"(1+0.010101)^(365 / 20)-1","value":"20.13%"}],"answer":"The return for the 20 days is 1.01%, which is about 18.43% a year (simple), or 20.13% with compounding."},"calculator":{"available":true,"inputs":[{"id":"d","label":"Discount for early payment","unit":"%","type":"number","default":1,"hint":""},{"id":"days","label":"Days paid early","unit":"days","type":"number","default":20,"hint":""}],"checks":[{"expr":"days>0 and d<1","message":"The days must be above zero and the discount below 100%."}],"steps":[{"id":"period","label":"Return for the period = d / (1 - d)","expr":"d/(1-d)","format":"pct2"},{"id":"ann","label":"Simple annualized = return x 365 / days","expr":"period*365/days","format":"pct2"},{"id":"comp","label":"Compounded = (1 + return)^(365 / days) - 1","expr":"(1+period)^(365/days)-1","format":"pct2"}],"results":["ann","comp"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"ann":0.18434343434343436,"comp":0.20131720944397502}},"finder":{"finds":"Annual return on paying a supplier early","needs":"Discount, days paid early"},"related":[{"slug":"cost-of-trade-credit","name":"Cost of Skipping an Early-Payment Discount"},{"slug":"annualized-hpr","name":"Annualizing a Holding Period Return"}],"related_ids":["F194","F025"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mtext>Annualized\xa0return</mtext><mo>=</mo><mfrac><mi>d</mi><mrow><mn>1</mn><mo>\u2212</mo><mi>d</mi></mrow></mfrac><mo>\xd7</mo><mfrac><mn>365</mn><mtext>days\xa0early</mtext></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\text{Annualized return}=\\\\frac{d}{1-d}\\\\times\\\\frac{365}{\\\\text{days early}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"dv01","name":"DV01 (Dollar Value of a Basis Point)"},"next":{"slug":"eps","name":"Earnings per Share (EPS)"},"lesson":null,"total":522}')}}]);